/**
 * Minimal logging interface accepted by all library constructors.
 *
 * When no logger is provided, logging is silently disabled ({@link noopLogger}).
 * Implement this interface to integrate with your own logging framework.
 */
export interface Logger {
    info(...args: any[]): void;
    error(...args: any[]): void;
    debug(...args: any[]): void;
    warn(...args: any[]): void;
}

const noop = () => {};

/**
 * A {@link Logger} that silently discards all messages.
 * Used as the default when no logger is supplied to a constructor.
 */
export const noopLogger: Logger = {
    info: noop,
    error: noop,
    debug: noop,
    warn: noop,
};