/**
 * Physical keyboard layout variant reported by a Work Louder device.
 */
export enum DeviceLayoutType {
    /** Layout has not been determined or does not apply. */
    unknown = "unknown",
    /** ANSI (American National Standards Institute) layout. */
    ansi = "ansi",
    /** ISO (International Organization for Standardization) layout. */
    iso = "iso",
    /** Universal layout (supports both ANSI and ISO key positions). */
    universal = "universal",
}