/**
 * Built-in LED animation effects supported by Work Louder device firmware.
 * Used in {@link SideLightingConfig} to control backlight and underglow.
 */
export enum LightingEffect {
    /** LEDs are turned off. */
    off = "off",
    /** All LEDs show a single static color. */
    solid = "solid",
    /** A colored segment travels across the LED strip. */
    snake = "snake",
    /** Continuously cycles through the full hue spectrum. */
    rainbow = "rainbow",
    /** LEDs fade in and out in a breathing pattern. */
    breath = "breath",
    /** A smooth color gradient spans the LED strip. */
    gradient = "gradient",
}
