/**
 * Transport layer used to communicate with a Work Louder device.
 */
export enum ConnectionType {
    /** UART serial connection (used by bootloader devices via ESP USB-CDC). */
    serial,
    /** USB HID connection (primary transport for runtime firmware). */
    hid,
}